inner=[[364,439],[387,433],[403,441],[416,460],[433,468],[445,478],[452,497],[468,511],[484,514],[498,523],[504,537],[520,543],[530,558],[530,578],[524,600],[524,614],[544,615],[542,636],[534,640],[530,661],[539,668],[529,696],[519,727],[505,747],[468,734],[441,725],[411,717],[391,718],[371,711],[353,699],[341,682],[334,660],[324,643],[315,630],[308,614],[310,594],[317,566],[321,545],[345,537],[368,526],[380,511],[366,502],[354,488],[350,476],[353,459],[351,446],[364,439]]
def coords(points):return [[round(float(v),7) for v in np.array([*p,1])@fit] for p in points]
base=dict(siteKey='edo',siteName='江户城（东京）',siteEnName='Edo Castle',period='明',wallPeriods=['明','清'],periodLabel='德川幕府江户城内外郭（17—19世纪；外堀1636年完成）',label=False,boundaryLabel=False,includeInDetails=True,inferredBoundary=True,lineWidth=1.1,sourceUrl=source,referenceUrl=source,sourceType='georeferenced-official-conservation-plan',calibrationUrl='data/edo-castle-calibration.json',attribution='千代田区・港区・新宿区《史跡江戸城外堀跡保存管理計画》(2008), fig.2-1-1; CODH historical place coordinates')
f=[dict(type='Feature',geometry=dict(type='Polygon',coordinates=[coords(inner)]),properties={**base,'id':'edo-complete-inner-enclosure','name':'江户城完整内郭范围（图示复原）','enName':'Complete Edo Castle inner enclosure (reference)','role':'area','note':'按三城区官方保存管理计划图2-1-1，结合内濠外缘标绘本城、西之丸、吹上、北之丸及西之丸下的内郭概略范围。不是仅把现代皇居东御苑当作完整江户城，也不是法定保护区测绘界。复原图示，非实测墙界。'}),dict(type='Feature',geometry=dict(type='LineString',coordinates=coords(outer)),properties={**base,'id':'edo-complete-outer-defence','name':'江户城完整外郭防御走向（外堀、土垒与河道）','enName':'Complete Edo outer moat / earthwork defence alignment','role':'wall','note':'沿官方图2-1-1的完整螺旋式外郭防御走向数字化：雉子桥—常盘桥—数寄屋桥、幸桥一带—虎之门、溜池—赤坂—四谷—牛込—神田川—浅草桥方向。含石垣、土垒、堀和借用河道，不等于全程连续石墙。已填埋或改造段以细虚线作历史复原参照；保留螺旋开口，不硬连成虚构闭合石墙。约14公里为原文对整个外堀体系的描述，不作为本数字线的精确测长。复原图示，非实测墙界。'})]
Path('data/edo-castle-circuits.geojson').write_text(json.dumps(dict(type='FeatureCollection',features=f),ensure_ascii=False,separators=(',',':'))+'\n',encoding='utf8')
report=dict(source=source,page=15,figure='2-1-1',sourceCrop=dict(originalRender=[1697,2400],box=[180,190,1515,1768],size=[1000,1182]),method='affine georeferencing of official full-map figure; manual digitization of inner enclosure and spiral outer defence',controls=[dict(name=n,pixel=p,wgs84=v,url=u,residualMeters=round(float(e),1)) for (n,p,v,u),e in zip(controls,res)],fitRmsMeters=round(float(np.sqrt(np.mean(res**2))),1),affinePixelToWGS84=fit.tolist(),innerPixels=inner,outerPixels=outer,notice='Control-point fit does not measure the historical positional uncertainty. Official map is a schematic full-defence reference, not a measured full surviving stone-wall circuit.')
Path('data/edo-castle-calibration.json').write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n',encoding='utf8')
im=Image.open('output/edo-castle/full-plan-crop.png').convert('RGB');d=ImageDraw.Draw(im);d.line([tuple(p) for p in outer],fill='#ff3a35',width=3);d.line([tuple(p) for p in inner],fill='#ffee00',width=3)
for _,p,_,_ in controls:d.ellipse((p[0]-4,p[1]-4,p[0]+4,p[1]+4),fill='#0000ff')
im.save('output/edo-castle/circuits-trace-review.png')
print(json.dumps(dict(features=2,rms=report['fitRmsMeters'],outerVertices=len(outer),innerVertices=len(inner))))
